---
name: Docs

# Versioned docs site (mike): `latest` tracks main, one frozen copy per release tag
# (v1.x.y), all living under docs/ on the gh-pages branch that mike maintains. The
# marketing page occupies the Pages ROOT beside it. Pages still deploys from a
# workflow artifact — the gh-pages branch is mike's ledger, not the Pages source —
# so publishing = mike commit → check the branch out → add marketing/ → upload.
on:
  push:
    branches: [main]
    # Path filters are not evaluated for tag pushes, so a release tag always publishes.
    tags: ["v*"]
    paths:
      - docs/site/**
      - docs/hooks/**
      - docs/overrides/**
      - marketing/**
      - mkdocs.yml
      - requirements-docs.txt
      - .github/workflows/docs.yml
  pull_request:
    paths:
      - docs/site/**
      - docs/hooks/**
      - docs/overrides/**
      - marketing/**
      - mkdocs.yml
      - requirements-docs.txt
      - .github/workflows/docs.yml
  workflow_dispatch:

permissions:
  contents: write # mike commits to gh-pages
  pages: write
  id-token: write

concurrency:
  group: pages
  cancel-in-progress: false

env:
  DISABLE_MKDOCS_2_WARNING: "true"

jobs:
  build:
    runs-on: ubuntu-latest
    outputs:
      version: ${{ steps.version.outputs.name }}
    steps:
      - uses: actions/checkout@v7

      - uses: actions/setup-python@v7
        with:
          python-version: "3.13"

      - run: pip install -r requirements-docs.txt

      # Every build (PRs included) must be strict-clean before anything is published.
      - run: mkdocs build --strict

      - name: Resolve the version to publish
        if: github.event_name != 'pull_request'
        id: version
        run: |
          if [[ "$GITHUB_REF" == refs/tags/v* ]]; then
            echo "name=${GITHUB_REF#refs/tags/}" >> "$GITHUB_OUTPUT"
            echo "title=${GITHUB_REF#refs/tags/}" >> "$GITHUB_OUTPUT"
          else
            echo "name=latest" >> "$GITHUB_OUTPUT"
            echo "title=latest (main)" >> "$GITHUB_OUTPUT"
          fi

      - name: Publish this version to gh-pages (mike)
        if: github.event_name != 'pull_request'
        # The tag name reaches the shell through env, never interpolated into the script.
        env:
          MIKE_VERSION: ${{ steps.version.outputs.name }}
          MIKE_TITLE: ${{ steps.version.outputs.title }}
        run: |
          git config user.name "github-actions[bot]"
          git config user.email "41898282+github-actions[bot]@users.noreply.github.com"
          git fetch origin gh-pages --depth=1 || true
          mike deploy --push --deploy-prefix docs --title "$MIKE_TITLE" "$MIKE_VERSION"
          mike set-default --push --deploy-prefix docs latest

      - name: Assemble the Pages artifact (gh-pages + marketing root)
        if: github.event_name != 'pull_request'
        env:
          MIKE_VERSION: ${{ steps.version.outputs.name }}
        run: |
          rm -rf site && mkdir site
          # Fetch again so the artifact is built from what mike just pushed, whatever the
          # remote-tracking ref says.
          git fetch origin gh-pages --depth=1
          git --work-tree=site checkout FETCH_HEAD -- docs
          git reset -q # the checkout above stages the paths; leave the index clean
          test -f "site/docs/$MIKE_VERSION/index.html" || {
            echo "::error::docs/$MIKE_VERSION is not in the artifact about to be deployed"
            exit 1
          }
          cp -r marketing/. site/

      - uses: actions/upload-pages-artifact@v5
        if: github.event_name != 'pull_request'
        with:
          path: site

  deploy:
    needs: build
    if: github.event_name != 'pull_request'
    runs-on: ubuntu-latest
    environment:
      name: github-pages
      url: ${{ steps.deployment.outputs.page_url }}
    steps:
      - id: deployment
        uses: actions/deploy-pages@v5

      # A deploy that reports success is not proof the version is being served (#2392: the
      # v1.2.0 tag's run was green while /docs/v1.2.0/ returned 404).
      - name: The published version is live
        env:
          PAGE_URL: ${{ steps.deployment.outputs.page_url }}
          VERSION: ${{ needs.build.outputs.version }}
        run: |
          for attempt in $(seq 1 20); do
            if curl -fsS "${PAGE_URL%/}/docs/versions.json?run=${GITHUB_RUN_ID}-${attempt}" \
                | grep -q "\"version\": \"${VERSION}\""; then
              echo "docs/${VERSION} is live"
              exit 0
            fi
            sleep 15
          done
          echo "::error::docs/${VERSION} is not in the live versions.json after 5 minutes"
          exit 1
