    expect(daysSince(at, Date.parse('2026-10-04T12:00:00Z'))).toBe(3);
  });
  it('is never negative and survives a bad timestamp', () => {
    expect(daysSince(at, Date.parse('2026-09-01T00:00:00Z'))).toBe(0);
    expect(daysSince('not a date')).toBe(0);
  });
});
